/* Closed elliptical project orbit. One visibility-gated frame loop, no 3D library. */
(()=>{
 const root=document.querySelector('#projets.orbit-projects');if(!root)return;const stage=root.querySelector('.orbit-project-stage'),track=root.querySelector('#projects'),dots=root.querySelector('.orbit-project-dots'),pause=root.querySelector('.orbit-project-pause'),status=root.querySelector('.orbit-project-status'),dialog=document.querySelector('#project-dialog'),reduced=matchMedia('(prefers-reduced-motion:reduce)'),small=matchMedia('(max-width:700px)'),TAU=Math.PI*2;
 let cards=[],indicators=[],count=0,step=TAU,phase=0,target=null,speed=0,frame=0,last=0,visible=false,sectionHover=false,hover=-1,focused=false,userPaused=false,resumeAt=0,wake=0,active=-1,radius=400,cardStep=420,cardWidth=400,stageWidth=1000,px=0,py=0,tx=0,ty=0,hoverRect=null,drag=null,suppressClick=false,wheelTimer=0;
 const mod=(n,m)=>(n%m+m)%m,clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
 function schedule(){if(!frame&&visible&&!document.hidden)frame=requestAnimationFrame(tick)}
 function hold(ms=2300){resumeAt=performance.now()+ms;clearTimeout(wake);wake=setTimeout(schedule,ms+25)}
 function select(index,announce=true){if(!count)return;index=mod(index,count);const difference=mod(index*step-phase+Math.PI,TAU)-Math.PI;target=phase+difference;speed=0;hold();if(reduced.matches){phase=target;target=null}if(announce)status.textContent=`Projet ${index+1} sur ${count} : ${cards[index].title}`;schedule()}
 function changeActive(index){if(index===active)return;active=index;cards.forEach((c,i)=>{c.el.classList.toggle('is-active',i===index);if(i===index)indicators[i].setAttribute('aria-current','true');else indicators[i].removeAttribute('aria-current')});root.querySelector('#work-current').textContent=String(index+1).padStart(2,'0')}
 function render(){if(!count)return;const index=mod(Math.round(phase/step),count);changeActive(index);const mobile=small.matches;
 cards.forEach((c,i)=>{let x,y,z,scale,angle,opacity,rear,shown=true;
 if(mobile){const rel=count===1?0:mod(i-phase/step+1.5,count)-1.5;x=rel*cardStep+(cardWidth/2+14-stageWidth/2);y=0;z=0;scale=1;angle=0;opacity=1;rear=Math.abs(rel)>1.3;shown=rel>-2&&rel<2.5}
 else{const theta=phase-i*step,s=Math.sin(theta),depth=Math.cos(theta),front=(depth+1)/2;x=-s*radius;y=-(1-front)*42;z=(depth-1)*160;scale=.78+.22*front;angle=-s*12;opacity=.24+.76*Math.pow(front,1.35);rear=depth<-.07;c.el.style.zIndex=String(Math.round(front*100)+1)}
 const tilt=!mobile&&i===active&&!reduced.matches?px*3:0,tiltX=!mobile&&i===active&&!reduced.matches?-py*2:0;c.el.style.transform=`translate3d(${x.toFixed(2)}px,${y.toFixed(2)}px,${z.toFixed(2)}px) rotateX(${tiltX.toFixed(2)}deg) rotateY(${(angle+tilt).toFixed(2)}deg) scale(${scale.toFixed(4)})`;const o=opacity.toFixed(3);if(c.opacity!==o){c.el.style.opacity=o;c.opacity=o}if(c.rear!==rear){c.el.classList.toggle('is-rear',rear);c.el.inert=rear;if(rear)c.el.setAttribute('aria-hidden','true');else c.el.removeAttribute('aria-hidden');c.rear=rear}c.el.style.visibility=shown?'visible':'hidden';
 });}
 function tick(now){frame=0;if(!visible||document.hidden||!count)return;const dt=last?Math.min((now-last)/1000,.04):1/60;last=now;let moving=false;
 if(target!==null&&!drag){const delta=target-phase;phase+=delta*(1-Math.exp(-dt*8));if(Math.abs(delta)<.0008){phase=target;target=null}else moving=true}
 const paused=reduced.matches||userPaused||hover>=0||focused||drag||dialog.open||now<resumeAt||count<2;const desired=paused?0:(sectionHover?.65:1);speed+=(desired-speed)*(1-Math.exp(-dt*8));if(Math.abs(speed-desired)<.001)speed=desired;if(target===null&&!drag&&speed>0){phase+=dt*TAU/18*speed;moving=true}
 const ex=hover===active?tx:0,ey=hover===active?ty:0;if(reduced.matches){px=py=0}else{px+=(ex-px)*(1-Math.exp(-dt*9));py+=(ey-py)*(1-Math.exp(-dt*9));if(Math.abs(ex-px)+Math.abs(ey-py)>.002)moving=true}
 render();root.classList.toggle('project-orbit-running',speed>.001&&!document.hidden);if(moving||speed>.001)frame=requestAnimationFrame(tick);else last=0;
 }
 function resize(){stageWidth=stage.clientWidth;cardWidth=cards[0]?.el.offsetWidth||350;cardStep=cardWidth+16;radius=Math.min(stageWidth*(innerWidth<1101?.35:.38),510);hoverRect=null;px=py=tx=ty=0;last=0;render();schedule()}
 function syncPause(){pause.disabled=reduced.matches;pause.setAttribute('aria-pressed',String(userPaused));pause.innerHTML=reduced.matches?'Animation réduite':userPaused?'Reprendre <span aria-hidden="true">▶</span>':'Pause <span aria-hidden="true">Ⅱ</span>'}
 function build(){cards=[...track.querySelectorAll('.work-slide')].map((el,i)=>{const action=el.querySelector('.open-project'),project=PORTFOLIO_PROJECTS.find(p=>p.id===action.dataset.project),number=PORTFOLIO_PROJECTS.indexOf(project)+1;let meta=el.querySelector('.orbit-project-meta');if(!meta){meta=document.createElement('div');meta.className='orbit-project-meta';const a=document.createElement('span'),b=document.createElement('span');a.textContent=`${String(number).padStart(2,'0')} / PROJECT`;b.textContent=project.category.toUpperCase();meta.append(a,b);el.prepend(meta)}if(!el.querySelector('.orbit-card-actions')){const actions=document.createElement('div');actions.className='orbit-card-actions';action.before(actions);actions.append(action);const detail=document.createElement('button');detail.type='button';detail.className='open-project orbit-card-detail';detail.dataset.project=project.id;detail.textContent='Détails';detail.setAttribute('aria-label',`Détails : ${project.title}`);actions.append(detail)}el.setAttribute('aria-label',`Projet ${i+1} : ${project.title}`);el.setAttribute('aria-roledescription','diapositive');el.querySelectorAll('img').forEach(img=>img.draggable=false);return {el,title:project.title,number,rear:null,opacity:null}});count=cards.length;root.classList.toggle('projects-empty',count===0);step=TAU/Math.max(count,1);phase=0;target=null;active=-1;hover=-1;focused=false;dots.replaceChildren();indicators=cards.map((c,i)=>{const button=document.createElement('button');button.type='button';button.textContent=String(c.number).padStart(2,'0');button.setAttribute('aria-label',`Afficher le projet ${c.number} : ${c.title}`);button.addEventListener('click',()=>select(i));dots.append(button);return button});root.querySelector('#work-total').textContent=String(count).padStart(2,'0');root.querySelector('#work-prev').disabled=count<2;root.querySelector('#work-next').disabled=count<2;hold(500);resize();syncPause()}
 root.querySelector('#work-prev').addEventListener('click',()=>select(active-1));root.querySelector('#work-next').addEventListener('click',()=>select(active+1));pause.addEventListener('click',()=>{userPaused=!userPaused;syncPause();schedule()});
 root.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){sectionHover=true;schedule()}});root.addEventListener('pointerleave',()=>{sectionHover=false;hover=-1;tx=ty=0;schedule()});
 track.addEventListener('pointerover',e=>{if(e.pointerType!=='mouse'||drag)return;const el=e.target.closest('.work-slide');const i=cards.findIndex(c=>c.el===el);if(i!==hover){hover=i;hoverRect=el?.getBoundingClientRect();tx=ty=0;schedule()}});track.addEventListener('pointerout',e=>{const el=e.relatedTarget instanceof Element?e.relatedTarget.closest('.work-slide'):null;if(!el||!track.contains(el)){hover=-1;tx=ty=0;schedule()}});
 stage.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('a,button'))return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,phase,started:false,vertical:false};target=null;hold();speed=0});
 stage.addEventListener('pointermove',e=>{if(drag&&e.pointerId===drag.id){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.started&&!drag.vertical&&Math.max(Math.abs(dx),Math.abs(dy))>8){if(Math.abs(dx)>Math.abs(dy)*1.1){drag.started=true;stage.setPointerCapture(e.pointerId);root.classList.add('is-dragging')}else drag.vertical=true}if(drag.started){phase=drag.phase-dx*(small.matches?step/cardStep:1/Math.max(radius,260));suppressClick=true;schedule()}return}if(hover>=0&&hoverRect&&!reduced.matches){tx=clamp((e.clientX-hoverRect.left)/hoverRect.width*2-1,-1,1);ty=clamp((e.clientY-hoverRect.top)/hoverRect.height*2-1,-1,1);schedule()}},{passive:true});
 function endDrag(e){if(!drag||e.pointerId!==drag.id)return;const moved=drag.started;drag=null;root.classList.remove('is-dragging');if(stage.hasPointerCapture(e.pointerId))stage.releasePointerCapture(e.pointerId);if(moved){if(reduced.matches)phase=Math.round(phase/step)*step;else target=Math.round(phase/step)*step;hold();setTimeout(()=>suppressClick=false,100)}schedule()}
 stage.addEventListener('pointerup',endDrag);stage.addEventListener('pointercancel',endDrag);stage.addEventListener('click',e=>{if(suppressClick){e.preventDefault();e.stopImmediatePropagation();suppressClick=false}},true);
 stage.addEventListener('wheel',e=>{if(e.ctrlKey||!(e.shiftKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)||stage.matches(':focus-visible')))return;e.preventDefault();const delta=(Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY)*(e.deltaMode===1?16:1);phase+=clamp(delta,-160,160)*.002;target=null;speed=0;hold();schedule();clearTimeout(wheelTimer);wheelTimer=setTimeout(()=>{if(reduced.matches)phase=Math.round(phase/step)*step;else target=Math.round(phase/step)*step;schedule()},180)},{passive:false});
 root.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();select(active+(e.key==='ArrowRight'?1:-1));if(e.target.closest('.work-slide'))stage.focus({preventScroll:true})}else if(e.key==='Home'||e.key==='End'){e.preventDefault();select(e.key==='Home'?0:count-1)}});
 track.addEventListener('focusin',e=>{focused=true;const i=cards.findIndex(c=>c.el.contains(e.target));if(i>=0&&i!==active)select(i,false);schedule()});track.addEventListener('focusout',()=>queueMicrotask(()=>{focused=track.contains(document.activeElement);schedule()}));dialog.addEventListener('close',()=>{hold(1000);schedule()});
 new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible){last=0;schedule()}else{cancelAnimationFrame(frame);frame=0;last=0;root.classList.remove('project-orbit-running')}},{threshold:0,rootMargin:'80px'}).observe(stage);new ResizeObserver(resize).observe(stage);addEventListener('portfolio:projects',build);document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(frame);frame=0;last=0;if(!document.hidden)schedule();else root.classList.remove('project-orbit-running')});reduced.addEventListener('change',()=>{speed=0;px=py=tx=ty=0;if(reduced.matches&&target!==null){phase=target;target=null}syncPause();render();schedule()});small.addEventListener('change',resize);build();
 const empty=document.createElement('p');empty.className='engineering-empty';empty.textContent='Aucun projet mobile présenté pour le moment.';empty.setAttribute('role','status');stage.append(empty);
 const reveal=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){root.classList.add('engineering-visible');reveal.disconnect()}},{threshold:.08});reveal.observe(root);
 addEventListener('portfolio:projects',()=>{if(!reduced.matches)stage.animate([{opacity:.35,translate:'0 7px'},{opacity:1,translate:'0 0'}],{duration:320,easing:'cubic-bezier(.22,1,.36,1)'})});
})();
